 const labels={list:"Ordner auflisten",write:"Testdatei schreiben",read:"Testdatei zurücklesen",rename:"Testdatei umbenennen",delete:"Testdatei löschen"},states={ok:"Erfolgreich",error:"Fehlgeschlagen",skipped:"Nicht geprüft"};
