  const controls=document.createElement("div");controls.className="toolbar run-retry";controls.innerHTML='<button type="button" class="secondary" data-retry-preview>Neue Vorschau</button>'+(!run.dryRun&&!retryJob.dryRun?'<button type="button" data-retry-run>Erneut starten</button>':"")+'<p class="helper">Neuer Run mit aktuellen Job-Einstellungen. Keine Fortsetzung ab der letzten Datei.</p>';status.append(controls);
